function row(p){const b=document.createElement('button');b.className='poi-row';const icon=document.createElement('i');icon.textContent=symbols[p.category];icon.setAttribute('aria-hidden','true');const text=document.createElement('span'),name=document.createElement('strong'),small=document.createElement('small');name.textContent=p.name;small.textContent=labels[p.category]+' · '+p.address;text.append(name,small);const arrow=document.createElement('b');arrow.textContent='↗';arrow.setAttribute('aria-hidden','true');b.append(icon,text,arrow);b.addEventListener('click',()=>openPlace(p));return b}
