let layoutFrame=0;function scheduleLayout(){if(!layoutFrame)layoutFrame=requestAnimationFrame(()=>{layoutFrame=0;layoutPins()})}
function layoutPins(){if(!enabled||!map)return;const container=map.getContainer(),mobile=innerWidth<=1000,w=mobile?136:160,h=54;const left=mobile?12:(innerWidth<=1190?250:305),right=container.clientWidth-(mobile?12:(innerWidth<=1190?345:390)),top=mobile?78:90,bottom=container.clientHeight-(mobile?120:115);const boxes=[];current().map(p=>({p,point:map.project(p.coord)})).sort((a,b)=>a.point.y-b.point.y).forEach(({p,point})=>{const root=markers.get(p.id)?.getElement();if(!root)return;const off=map.getZoom()<13||point.x<left-150||point.x>right+150||point.y<0||point.y>container.clientHeight;root.hidden=off;if(off)return;let best=null;for(const dy of [-h-18,18,-h-85,85,-h-150,150,...Array.from({length:Math.max(1,Math.floor((bottom-top)/(h+10)))},(_,i)=>top+i*(h+10)-point.y)])for(const dx of [-w-20,20,-w/2,left-point.x,right-w-point.x]){const x=Math.max(left,Math.min(right-w,point.x+dx)),y=Math.max(top,Math.min(bottom-h,point.y+dy));let overlap=0;for(const b of boxes)overlap+=Math.max(0,Math.min(x+w+8,b.x+w)-Math.max(x-8,b.x))*Math.max(0,Math.min(y+h+8,b.y+h)-Math.max(y-8,b.y));const score=overlap*100+Math.hypot(x+w/2-point.x,y+h/2-point.y);if(!best||score<best.score)best={x,y,score}}if(!best)return;boxes.push(best);const button=root.querySelector('button'),dx=best.x-point.x,dy=best.y-point.y;button.style.transform='translate('+dx+'px,'+dy+'px)';const endX=Math.max(best.x,Math.min(best.x+w,point.x)),endY=Math.max(best.y,Math.min(best.y+h,point.y));const stem=root.querySelector('.poi-stem');stem.style.width=Math.hypot(endX-point.x,endY-point.y)+'px';stem.style.transform='rotate('+Math.atan2(endY-point.y,endX-point.x)+'rad)';})}
function setEnabled(on,move=true){enabled=on;el('poi-toggle').setAttribute('aria-pressed',String(on));el('poi-toggle').textContent=on?'Ocultar sitios':'＋ Ver sitios recomendados';el('poi-filters').hidden=!on;render();if(on&&move)fitPlaces();}
function fitPlaces(){const list=current();if(!map||!list.length)return;inOverview=false;map.stop();const coords=list.map(p=>p.coord),z=window.BED_ZONES.find(z=>z.id===getZone());if(z)coords.push([z.coord[1],z.coord[0]]);const mobile=innerWidth<=1000,pad=mobile?{top:90,bottom:125,left:65,right:65}:{top:120,bottom:120,left:innerWidth<=1190?275:340,right:innerWidth<=1190?370:425};const west=Math.min(...coords.map(c=>c[0])),east=Math.max(...coords.map(c=>c[0])),south=Math.min(...coords.map(c=>c[1])),north=Math.max(...coords.map(c=>c[1]));const merc=lat=>Math.log(Math.tan(Math.PI/4+lat*Math.PI/360))/(2*Math.PI),c=map.getContainer();const zoom=Math.min(15.3,Math.log2(Math.min(Math.max(100,c.clientWidth-pad.left-pad.right)/(512*Math.max(.001,east-west)/360),Math.max(100,c.clientHeight-pad.top-pad.bottom)/(512*Math.max(.000003,merc(north)-merc(south)))))-.45);map.easeTo({center:[(west+east)/2,(north+south)/2],zoom,padding:pad,pitch:el('view3d').getAttribute('aria-pressed')==='true'?(mobile?35:45):0,bearing:0,duration:matchMedia('(prefers-reduced-motion: reduce)').matches?0:900});}
